// Coordinate map shared by experimental fixed-boundary corrections.
#ifndef CUMES_BENCHMARKS_CORRECTION_COORDINATES_CUH_
#define CUMES_BENCHMARKS_CORRECTION_COORDINATES_CUH_

#include "cumes/config/device_params.hpp"
#include "cumes/runtime/cuda_status.hpp"

#include <cuda_runtime.h>

#include <cmath>

namespace block_bench {
namespace correction_detail {

// The unknown q has the same normalized, m=1-mixed coordinates as production
// preconditioned forces and velocities. Axis dependencies are regenerated by
// EquilibriumOperator before synthesis, so they are not independent unknowns.
__host__ __device__ inline bool active(int component,
                                       int m,
                                       int n,
                                       int j,
                                       int ns,
                                       bool fix_m1) {
    if (component == 2) return m > 0 && j > 0;
    if (component == 5) return n > 0 && j > 0;
    if (j == ns - 1 || (j == 0 && m > 0)) return false;
    if (component == 0) return true;
    if (component == 1) return m > 0;
    if (component == 3) return m > 0 && n > 0;
    return n > 0 && !(m == 1 && fix_m1);
}

template <class T>
__global__ void pack_kernel(const T* d_residual,
                            T* d_q,
                            int ns,
                            int mnmax,
                            int ntor,
                            bool fix_m1) {
    const int i = blockIdx.x * blockDim.x + threadIdx.x;
    const int count = ns * mnmax;
    if (i >= 6 * count) return;
    const int component = i / count, mode = (i % count) / ns, j = i % ns;
    const int m = mode / (ntor + 1), n = mode % (ntor + 1);
    d_q[i] = active(component, m, n, j, ns, fix_m1) ? d_residual[i] : T(0);
}

template <class T, bool Trial>
__global__ void physical_kernel(const T* d_base,
                                const T* d_q,
                                T* d_result,
                                int ns,
                                int mnmax,
                                int ntor,
                                bool fix_m1,
                                T scale,
                                const T* d_scale) {
    const int i = blockIdx.x * blockDim.x + threadIdx.x;
    const int count = ns * mnmax;
    if (i >= count) return;
    const int mode = i / ns, j = i % ns;
    const int m = mode / (ntor + 1), n = mode % (ntor + 1);
    const T basis = (m == 0 ? T(1) : sqrt(T(2))) * (n == 0 ? T(1) : sqrt(T(2)));
    T q[6];
    for (int c = 0; c < 6; ++c)
        q[c] = active(c, m, n, j, ns, fix_m1) ? d_q[c * count + i] : T(0);
    if (m == 1) {
        // Production descent undoes this pair without a 1/sqrt(2) factor.
        // A fixed mixed Zcs coordinate therefore permits equal PHYSICAL
        // Rss/Zcs increments; masking physical Zcs would freeze the wrong DOF.
        const T rss = q[3], zcs = q[4];
        q[3] = rss + zcs;
        q[4] = rss - zcs;
    }
    if constexpr (Trial) {
        if (d_scale) scale *= *d_scale;
    }
    for (int c = 0; c < 6; ++c) {
        const int index = c * count + i;
        if constexpr (Trial) {
            // Reproduce descent's increment order, including the basis last.
            // Direct copy for a zero increment preserves signed zeros and all
            // fixed boundary, dependent-axis and null-parity baseline values.
            d_result[index] = q[c] == T(0) || scale == T(0)
                                  ? d_base[index]
                                  : d_base[index] + (scale * q[c]) * basis;
        } else {
            d_result[index] = q[c] * basis;
        }
    }
}

}  // namespace correction_detail

// All pointers address contiguous [Rcc,Zsc,Lsc,Rss,Zcs,Lcs][mode][surface]
// slabs. Input/output aliasing is supported. This helper owns no buffers.
template <class T>
class CorrectionCoordinates {
   public:
    using val_type = T;

    CorrectionCoordinates(const DeviceParams<T>& p, bool fix_m1)
        : ns_(p.ns), mnmax_(p.mnmax), ntor_(p.ntor), fix_m1_(fix_m1) {}

    int size() const { return 6 * ns_ * mnmax_; }
    void set_fix_m1(bool fix_m1) { fix_m1_ = fix_m1; }

    void enqueue_pack(const T* d_residual, T* d_q, cudaStream_t stream) const {
        correction_detail::
            pack_kernel<<<(size() + 255) / 256, 256, 0, stream>>>(
                d_residual, d_q, ns_, mnmax_, ntor_, fix_m1_);
        cumes::check_cuda(cudaGetLastError(), "correction coordinate mask");
    }

    void enqueue_physical(const T* d_q,
                          T* d_physical,
                          cudaStream_t stream) const {
        correction_detail::physical_kernel<T, false>
            <<<(ns_ * mnmax_ + 255) / 256, 256, 0, stream>>>(
                nullptr, d_q, d_physical, ns_, mnmax_, ntor_, fix_m1_, T(1),
                nullptr);
        cumes::check_cuda(cudaGetLastError(), "correction physical direction");
    }

    // Effective scale is scale * *d_scale when the optional device scalar is
    // present, allowing norm-scaled finite differences without a host fence.
    void enqueue_trial(const T* d_base,
                       const T* d_q,
                       T* d_trial,
                       T scale,
                       cudaStream_t stream,
                       const T* d_scale = nullptr) const {
        correction_detail::physical_kernel<T, true>
            <<<(ns_ * mnmax_ + 255) / 256, 256, 0, stream>>>(
                d_base, d_q, d_trial, ns_, mnmax_, ntor_, fix_m1_, scale,
                d_scale);
        cumes::check_cuda(cudaGetLastError(), "correction physical trial");
    }

   private:
    int ns_, mnmax_, ntor_;
    bool fix_m1_;
};

}  // namespace block_bench
#endif
